def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.8)
        return float(max(0.0, safe_bid))

    total_players = 1 + len(alive)
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < total_players

    opp_signals = []
    max_prev_bid = 0.0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is None:
            prev_bid = opp.get('daily_salary', DAILY_SALARY) * 0.7
        prev_bid = float(prev_bid)

        threat = prev_bid
        if opp.get('budget', 0) < prev_bid:
            threat = float(opp.get('budget', 0))
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            threat = max(threat, min(float(opp.get('budget', 0)), prev_bid * 1.15 + 8.0))
        opp_signals.append(threat)
        if threat > max_prev_bid:
            max_prev_bid = threat

    opp_signals.sort(reverse=True)
    target_to_beat = opp_signals[int(0)] if len(opp_signals) >= 1 else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if scarcity:
        urgency += 2
    elif float(supply) <= 18.0:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency <= 1:
        base = DAILY_SALARY * 0.38
        if not scarcity and float(supply) >= 22.0:
            base = DAILY_SALARY * 0.28
        bid = min(base, budget)
    elif urgency == 2:
        bid = max(DAILY_SALARY * 0.6, target_to_beat + 2.0)
    elif urgency == 3:
        bid = max(DAILY_SALARY * 0.78, target_to_beat + 4.0)
    elif urgency == 4:
        bid = max(DAILY_SALARY * 0.95, target_to_beat + 7.0)
    else:
        bid = max(DAILY_SALARY * 1.1, target_to_beat + 12.0)

    if budget < DAILY_SALARY * 1.2 and urgency <= 2:
        bid = min(bid, budget * 0.72)

    if budget > 250 and scarcity and urgency >= 3:
        bid = max(bid, target_to_beat + 10.0)

    if hp >= 8 and no_water_days == 0 and not scarcity and float(supply) >= 21.0:
        bid = min(bid, DAILY_SALARY * 0.42)

    if hp <= 1 or no_water_days >= 3:
        bid = max(bid, min(budget, target_to_beat + 15.0))

    bid = min(float(budget), float(bid))
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are plausible per day; use it to scale aggressiveness
    # (supply is float; indices must be int, avoid floor-division to list indices)
    # target_units ~ supply / WATER_REQ
    target_units = supply / float(WATER_REQ) if WATER_REQ else 1.0

    # Base bid: aim to secure water when supply is moderate, but avoid overpaying.
    # If supply is closer to MIN_SUPPLY, competition is tighter.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # If yesterday had very high pressure (someone bid near salary), we raise our bid.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = highest_prev_bid / float(DAILY_SALARY)

    if pressure >= 1.2:
        base = DAILY_SALARY * (0.85 + 0.1 * (1.0 - supply_ratio))
    elif pressure >= 0.9:
        base = DAILY_SALARY * (0.70 + 0.15 * (1.0 - supply_ratio))
    else:
        base = DAILY_SALARY * (0.55 + 0.20 * (1.0 - supply_ratio))

    # If our HP is low or we already went multiple days without water, bid more.
    if hp <= 2:
        base *= 1.25
    elif hp <= 4:
        base *= 1.10

    if no_water_days >= 2:
        base *= 1.15

    # If yesterday's highest bid was moderate, try to slightly undercut/beat by a small margin.
    # We don't know today's hidden bids, so we bias toward winning without maxing.
    if highest_prev_bid > 0:
        # Add a small increment capped to avoid runaway spending
        base = min(base, highest_prev_bid + DAILY_SALARY * 0.15)

    # Convert base into final bid with budget cap.
    # Also ensure we bid at least a small amount when budget allows.
    final_bid = max(0.0, min(budget, base))

    # If budget is very low, bid whatever remains to avoid immediate death.
    if budget <= DAILY_SALARY * 0.25:
        final_bid = min(budget, DAILY_SALARY * 0.9)

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0
    if my_status['hp'] <= 3:
        bid = avg_prev_bid * 1.2
    else:
        bid = avg_prev_bid * 0.9
    return min(float(my_status['budget']), float(bid))
